<?php
namespace App\Controllers;
use App\Support\{Auth,View,Request,Response,Csrf,Database,TenantContext};use App\Repositories\{ServiceRepository,ClientServiceRepository};use App\Services\{ServiceLifecycleService,RequirementEngine,TaskGenerationService,OperationsOrchestrator};
final class ServiceController { public function index():void{Auth::requireLogin();View::render('services/index',['services'=>(new ServiceRepository)->all()]);} public function show($id):void{Auth::requireLogin();$r=(new ServiceRepository)->find((int)$id);$s=Database::pdo()->prepare('SELECT * FROM service_requirements WHERE tenant_id=? AND service_id=? ORDER BY sort_order');$s->execute([TenantContext::id(),$id]);View::render('services/show',['service'=>$r,'requirements'=>$s->fetchAll()]);} public function request():void{Auth::requireLogin();$r=new Request();if(!Csrf::check($r->input('_csrf')))Response::json(['error'=>'csrf'],419);$id=(new ServiceLifecycleService)->request((int)$r->input('client_id'),(int)$r->input('service_id'),$r->input('business_id')?(int)$r->input('business_id'):null);(new TaskGenerationService)->fromRequirements($id,(int)$r->input('client_id'));(new OperationsOrchestrator)->handle('SERVICE_REQUESTED',['client_service_id'=>$id,'client_id'=>(int)$r->input('client_id')]);Response::json(['success'=>true,'id'=>$id]);} public function requirements($id):void{Auth::requireLogin();$s=Database::pdo()->prepare('SELECT csr.*,r.name,r.description,r.requirement_type,r.required FROM client_service_requirements csr JOIN service_requirements r ON r.id=csr.requirement_id WHERE csr.tenant_id=? AND csr.client_service_id=?');$s->execute([TenantContext::id(),$id]);View::render('services/requirements',['rows'=>$s->fetchAll(),'client_service_id'=>$id]);}}
